Generate a standalone C reproducer that triggers this vulnerability:

File: bfd/coff-rs6000.c
Line: 4211
Function: xcoff_generate_rtinit
Bug type: integer-overflow
CWE: CWE-190
Explanation: string_table_size is accumulated from initsz and finisz (when > 9) and then incremented by 4, without overflow checks. If the sums overflow bfd_size_type, bfd_zmalloc allocates an undersized string table. Later, the code copies initsz/finisz bytes into this table (lines 4274 and 4310), which can overflow the heap buffer.

Source context:
```c
     4171: 
     4172:   data_buffer_size = 0x0040 + initsz + finisz;
     4173:   data_buffer_size = (data_buffer_size + 7) &~ (bfd_size_type) 7;
     4174:   data_buffer = NULL;
     4175:   data_buffer = (bfd_byte *) bfd_zmalloc (data_buffer_size);
     4176:   if (data_buffer == NULL)
     4177:     return false;
     4178: 
     4179:   if (initsz)
     4180:     {
     4181:       val = 0x10;
     4182:       bfd_h_put_32 (abfd, val, &data_buffer[0x04]);
     4183:       val = 0x40;
     4184:       bfd_h_put_32 (abfd, val, &data_buffer[0x14]);
     4185:       memcpy (&data_buffer[val], init, initsz);
     4186:     }
     4187: 
     4188:   if (finisz)
     4189:     {
     4190:       val = 0x28;
     4191:       bfd_h_put_32 (abfd, val, &data_buffer[0x08]);
     4192:       val = 0x40 + initsz;
     4193:       bfd_h_put_32 (abfd, val, &data_buffer[0x2C]);
     4194:       memcpy (&data_buffer[val], fini, finisz);
     4195:     }
     4196: 
     4197:   val = 0x0C;
     4198:   bfd_h_put_32 (abfd, val, &data_buffer[0x0C]);
     4199: 
     4200:   scnhdr.s_size = data_buffer_size;
     4201: 
     4202:   /* string table */
     4203:   string_table_size = 0;
     4204:   if (initsz > 9)
     4205:     string_table_size += initsz;
     4206:   if (finisz > 9)
     4207:     string_table_size += finisz;
     4208:   if (string_table_size)
     4209:     {
     4210:       string_table_size += 4;
>>>  4211:       string_table = (bfd_byte *) bfd_zmalloc (string_table_size);
     4212:       if (string_table == NULL)
     4213: 	{
     4214: 	  free (data_buffer);
     4215: 	  return false;
     4216: 	}
     4217: 
     4218:       val = string_table_size;
     4219:       bfd_h_put_32 (abfd, val, &string_table[0]);
     4220:       st_tmp = string_table + 4;
     4221:     }
     4222: 
     4223:   /* symbols
     4224:      0. .data csect
     4225:      2. __rtinit
     4226:      4. init function
     4227:      6. fini function
     4228:      8. __rtld  */
     4229:   memset (syment_ext, 0, 10 * SYMESZ);
     4230:   memset (reloc_ext, 0, 3 * RELSZ);
     4231: 
     4232:   /* .data csect */
     4233:   memset (&syment, 0, sizeof (struct internal_syment));
     4234:   memset (&auxent, 0, sizeof (union internal_auxent));
     4235:   memcpy (syment._n._n_name, data_name, strlen (data_name));
     4236:   syment.n_scnum = 1;
     4237:   syment.n_sclass = C_HIDEXT;
     4238:   syment.n_numaux = 1;
     4239:   auxent.x_csect.x_scnlen.u64 = data_buffer_size;
     4240:   auxent.x_csect.x_smtyp = 3 << 3 | XTY_SD;
     4241:   auxent.x_csect.x_smclas = XMC_RW;
     4242:   bfd_coff_swap_sym_out (abfd, &syment,
     4243: 			 &syment_ext[filehdr.f_nsyms * SYMESZ]);
     4244:   bfd_coff_swap_aux_out (abfd, &auxent, syment.n_type, syment.n_sclass, 0,
     4245: 			 syment.n_numaux,
     4246: 			 &syment_ext[(filehdr.f_nsyms + 1) * SYMESZ]);
     4247:   filehdr.f_nsyms += 2;
     4248: 
     4249:   /* __rtinit */
     4250:   memset (&syment, 0, sizeof (struct internal_syment));
     4251:   memset (&auxent, 0, sizeof (union internal_auxent));
```

The reproducer will be compiled with:
  clang -fsanitize=address -g -O0 -I/tmp/binutils_upstream reproducer.c -L/tmp/binutils_upstream/build/.libs -ltiff -lm

The project source root is: /tmp/binutils_upstream
